-- Ticket C1: add orders.region text NOT NULL DEFAULT 'EU'
--
-- On PostgreSQL 17, ADD COLUMN with a constant (non-volatile) default is
-- metadata-only: the default is stored as attmissingval, so there is no
-- table rewrite and no scan. Existing rows read back as 'EU', and new rows
-- get 'EU' from the column default, so app inserts need no change.
--
-- The real risk is the lock. ALTER TABLE needs ACCESS EXCLUSIVE on orders.
-- The analytics transaction holds ACCESS SHARE for 6-12 s, so a plain
-- ALTER would queue behind it, and every app statement on orders would queue
-- behind the ALTER. That would breach the 500 ms limit. So the script takes
-- the lock with a short lock_timeout and retries in the gaps between
-- analytics transactions. Each failed attempt rolls back its subtransaction
-- and releases everything, so the app is delayed by at most one 50 ms wait
-- per attempt.
--
-- No new objects are created, so no grants are needed: the app's existing
-- table-level SELECT/INSERT/UPDATE cover the new column.
--
-- SET LOCAL only affects this transaction; no server, database or role
-- settings are changed.

DO $$
DECLARE
  deadline timestamptz := clock_timestamp() + interval '36 seconds';
  attempt  int := 0;
BEGIN
  LOOP
    -- Idempotence: if a previous run already added the column, stop.
    -- This catalog read takes no lock on orders.
    IF EXISTS (
      SELECT 1
        FROM pg_attribute
       WHERE attrelid = 'orders'::regclass
         AND attname  = 'region'
         AND NOT attisdropped
    ) THEN
      RAISE NOTICE 'orders.region already exists; nothing to do';
      RETURN;
    END IF;

    attempt := attempt + 1;
    BEGIN
      SET LOCAL lock_timeout = '50ms';
      ALTER TABLE orders ADD COLUMN region text NOT NULL DEFAULT 'EU';
      RAISE NOTICE 'orders.region added on attempt %', attempt;
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      IF clock_timestamp() > deadline THEN
        RAISE EXCEPTION 'could not lock orders for ADD COLUMN within budget (% attempts)',
          attempt;
      END IF;
      PERFORM pg_sleep(0.05);
    END;
  END LOOP;
END
$$;
